(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["co"] = {"ui":{"skip":"Andà à u cuntenutu","back":"← Torna à AI-gile","lang.button":"Lingua: {name}","lang.dialog":"Sceglie una lingua","lang.search":"Circà lingue","lang.none":"Nisuna lingua currisponde","lang.notYet":"{name} ùn hè ancu traduttu","theme.aria":"Cambià tema: chjaru, scuru o neru","theme.toLight":"Passà à u tema chjaru","theme.toDark":"Passà à u tema scuru","theme.toBlack":"Passà à u tema neru (neru veru, dolce per i schermi OLED)","words.underline":"Sottulineà ste parolle nantu à a pagina","words.underlineHelp":"Passa sopra o tocca una parolla puntighjata per vede ciò ch'ella vole dì.","words.col.todo":"Carte sceglite per avà: a squadra principia cù queste dopu.","words.col.doing":"Una IA travaglia nantu à sta carta avà.","words.col.review":"Una IA hà finitu u travagliu; un'altra u verifica nanzu ch'ellu ghjunghji à tè.","words.col.verify":"Ti aspetta: pruvalu è dì s'ellu funziona.","words.col.team":"E to note o risposte, in attesa chì a squadra e piglii.","words.col.done":"Finita è accettata.","index.title":"AI-gile: a to squadra di sviluppu AI, nantu à una sola tavula","index.description":"AI-gile hè una tavula kanban per e squadre AI chì prugrammanu. Travaglianu mentre dorme; tù ricevi un picculu mucchjettu di cose à decide, pruvà è accettà.","hero.logoAlt":"Icona di a tavula AI-gile","hero.h1.html":"A to squadra di sviluppu AI, nantu à una sola&nbsp;tavula.","hero.alpha":"🐣 Pre-alfa chjosa","hero.alphaTitle":"Prestu è micca compiu: grazie di pruvallu!","hero.lede":"Custruiscenu mentre dorme. Ti svegli cù un mucchjettu cortu: qualchì dumanda, qualchì cosa à pruvà, un diamante viulettu o dui. Clic, accettatu, torna à u to caffè.","dl.windows":"App per Windows","dl.browser":"Eseguitela in u navigatore","dl.messenger":"📱 Messenger per u to telefuninu","dl.soon":"Prestu dispunibule","dl.notify":"🔔 Avvisami quandu s'apre","dl.notifySmall":"Alfa o beta","hero.secondary":"Agile, ma a squadra ùn hà mai bisognu di u caffè di a stand-up. (Face e stand-up listessu.)","pitch.h2":"AI-gile in tante parolle quant'è tù vo","pitch.lede":"Sceglie una lunghezza, da una parolla à 144. Ogni lunghezza hè una discrizzione propria, scritta per quella misura. Tira u cursore o usa e fraccette di a tastera.","pitch.rangeLabel":"Lunghezza in parolle","pitch.dice":"🎲 un'altra versione","pitch.words.one":"{n} parolla","pitch.words.other":"{n} parolle","pitch.letters.one":"{n} lettera","pitch.letters.other":"{n} lettere","pitch.chars.one":"{n} carattere","pitch.chars.other":"{n} caratteri","count.line.html.one":"{n} carta nantu à a tavula avà","count.line.html.other":"{n} carte nantu à a tavula avà","people.humans.html.one":"👥 {n} umanu","people.humans.html.other":"👥 {n} umani","people.agents.html.one":"🤖 {n} agente","people.agents.html.other":"🤖 {n} agenti","people.working.html.one":"⚡ {n} à u travagliu avà","people.working.html.other":"⚡ {n} à u travagliu avà","pre.title":"AI-gile : quì si custruisce qualcosa","pre.description":"Quì si custruisce qualcosa. Una tavula induve e squadre AI custruiscenu ciò chì dumandate, è v'amparanu strada facendu. Per avà, pre-alfa chjosa cù l'amichi.","pre.h1":"Quì si custruisce qualcosa. 🤫","pre.line":"Una tavula induve e squadre AI custruiscenu ciò chì dumandate, è v'amparanu strada facendu. Per avà, pre-alfa chjosa cù l'amichi.","pre.btn":"🔔 Avvisami quandu s'apre","pre.peek":"Daretu à u vetru : a vera tavula, in diretta. Ogni carta hè una striscia culurita.","pre.peekFake":"Daretu à u vetru : eccu cumu pare una tavula à u travagliu.","pre.night":"🌙 U guardianu di notte hè in carica · 😴 l'omu si riposa","features.aria":"Ciò chì face","f.pile.h":"Un mucchjettu per tè","f.pile.html":"<b>Per tè</b> riunisce tuttu ciò chì ti aspetta, in tutti i prugetti: dumande, cose à pruvà, travagli chì solu una persona pò fà. A to fila dice cio chì vene dopu è quantu tempu ci vole.","f.sleep.h":"Squadre chì travaglianu mentre dorme","f.sleep.p":"Ogni prugettu hà un capu è una squadra d'agenti AI. Lascia un cumentu nantu à una carta è a squadra si sveglia, face u travagliu è ti u rende cù i passi chì pò seguità ancu una persona stanca.","f.tester.h":"Un tester AI verifica prima","f.tester.p":"Nanzu chì qualcosa ti ghjunghje, un tester seguita i passi in una copia di l'app è mostra ciò chì hà vistu, cù una cattura di schermu. Sfoglia quelle chì sò passate è accetta cù un clic.","f.proof.h":"Prove, micca prumesse","f.proof.p":"Ogni cunsegna mostra ciò chì hè cambiatu: i fugliali, e differenze, e catture di schermu. Ùn ci hè bisognu d'apre ogni app per sapè s'ellu hè compiu.","f.chat.h":"Chjachjerà cù i to capi","f.chat.p":"Una barra à u stilu di Discord: una icona per prugettu, diamanti viulettu per ciò chì ti vole. Manda una idea à un capu; a trasforma in carte è in un pianu, cù un buttone ✅ Go.","f.tidy.h":"Si tene in ordine solu","f.tidy.p":"E carte parenti si unisconu in una, i tituli imbrugliati sò currettati, è un cuntrollu di i token tene u codice leggeru. Menu cose trà e quali passà, menu à pensà.","f.private.h":"Toiu, nantu à u to urdinatore","f.private.li1":"A tavula gira nantu à a to macchina è risponde solu à tè.","f.private.li2":"I missaghji privati trà e persone sò cifrati da un capu à l'altru.","f.private.li3":"Nisun contu, nisun tracciatore, nisun cookie.","f.lang.h":"In a to lingua","f.lang.p":"Più di 120 lingue, da l'olandese, u gallese è u giapponese finu à u pirata, Yoda è u klingon, cù un cambiu prestu in inglese per i termini di u mistieru.","f.service.h":"Da un'idea à un veru serviziu","f.service.p":"Hai custruitu cù l'IA qualcosa chì a ghjente adopra avà? Marcalu cum'è serviziu è u tavulinu t'aiuta à gestillu bè: cuntrolli di funziunamentu, una pagina di statu publica, incidenti cù un rapportu, cambiamenti chì anu bisognu d'un Si va, copie di salvezza verificate ogni ghjornu. L'Aiutu t'insegna ogni passu strada facendu.","msgr.h2":"AI-gile Messenger : a to squadra in stacca","msgr.p1":"Parla cù a to squadra IA senza apre a tavula. Chjachjareghja cù i capi di i to prughjetti è cù i to amichi, è vedi i passi di prova d'una scheda è rispondeli, tuttu da u to telefuninu.","msgr.p2":"Per accuppiallu, scanna un codice QR nantu à a to tavula. Prima volta ? Una chjachjarata demo simpatica ti face vede tuttu.","msgr.when":"Prima Android, dopu una versione web per i telefunini è l'iPhone.","msgr.who":"U capu di u to prughjettu","msgr.b1":"A currezzione di u modu scuru hè pronta. Voli i passi di prova ?","msgr.b2":"Iè, per piacè !","msgr.b3":"1. Apre Impostazioni. 2. Sceglie Scuru. Pare ghjustu ?","tl.aria":"Cronologia da a prima cunversazione à u pianu di strada","tl.h2":"Da a prima chjachjarata à ciò chì vene dopu","tl.lede":"Date è ore vere, in u to fusu orariu. Dopu à oghje hè u pianu, senza date prumesse.","tl.today":"Oghje","tl.planned":"previstu","tl.doing":"in corsu","tl.cards.one":"{n} carta","tl.cards.other":"{n} carte","join.h2":"Unisciti","join.lede":"AI-gile hè custruitu da un stranu barbutu cù l'AuDHD è qualchì battaglia cù a salute mentale, è da un gran numeru d'agenti pazienti. Hè privatu per avà, in una alfa chjosa cù l'amichi. Ti piacerebbe pruvallu quandu s'aprerà?","join.btn":"Signalà u to interessu","join.small":"Ti scriveremu un email, nunda più","footer.tag":"AI-gile. Nisun tracciatore, nisun cookie, nisun caffè di stand-up.","footer.licence":"Licenza d'impresa","footer.status":"Statu","footer.privacy":"Ciò chì guardemu","footer.thanks":"Chjame grazie à ChilledChat","form.sending":"Mandu in corsu…","form.failed":"Ùn hà micca fattu: ripruva più tardi.","form.offline":"Impussibule di ghjunghje à AI-gile: ripruva più tardi.","form.keep":"L'usemu solu per risponde ti, po u scancellemu. Nisun tracciatore, nisun cookie.","form.keepLink":"Ciò chì guardemu","interest.title":"AI-gile: avvisami quandu s'apre l'alfa","interest.description":"Lascia u to email per sapè quandu s'apre l'alfa chjosa o a beta di AI-gile.","interest.h1":"🔔 Avvisami quandu s'apre","interest.lede":"AI-gile hè in pre-alfa chjosa. Lascia u to email è ti scriveremu una volta, quandu ci serà un locu per tè.","interest.email":"U to email","interest.which":"Quale prova?","interest.alpha":"Alfa chjosa: prestu, grezza, tanti cambiamenti","interest.beta":"Beta: più stabile, dopu","interest.both":"L'una o l'altra, quella chì vene prima","interest.submit":"Mettimi nantu à a lista","interest.thanks":"Grazie! Sì nantu à a lista.","licence.title":"AI-gile: licenza d'impresa","licence.description":"Usi AI-gile in a to impresa? Dumanda una licenza d'impresa gratuita.","licence.h1":"📜 Licenza d'impresa","licence.lede":"Usi AI-gile à u travagliu? Dicci quale sì è ciò chì faci. S'ellu face un pocu di bè, a licenza hè gratuita.","licence.company":"Impresa","licence.website":"Situ web","licence.what":"Ciò chì faci","licence.how":"Cumu aiuta u mondu","licence.email":"Email","licence.submit":"Dumandà","licence.thanks":"Grazie! Ti risponderemu per email.","status.title":"Statu di AI-gile","status.h1":"Statu di AI-gile","status.quiet":"Tuttu tranquillu","status.intro":"AI-gile funziona avà? Sta pagina verifica u situ, u spartimentu di e tavule, e chjamate è u scaricamentu ogni 5 minuti.","status.up":"Funziona (hà rispostu in {ms} ms)","status.slow":"Ùn hà micca rispostu à l'ultima verificazione, ripruvemu","status.down":"In panna: ùn hà micca rispostu à l'ultime duie verificazioni","status.svc.web":"Situ web","status.svc.web.offers":"Stu situ: ciò ch'ellu hè AI-gile, è u furmulariu d'interessu","status.svc.boards":"Spartimentu di e tavule","status.svc.boards.offers":"Tavule publiche, messaghji trà amichi è invitazioni","status.svc.calls":"Chjamate","status.svc.calls.offers":"Voce, video è spartimentu di screnu in AI-gile","status.svc.download":"Scaricamentu","status.svc.download.offers":"L'installatore Windows è i liami d'invitazione","status.checking":"Verificà in corsu…","status.offline":"Impussibule di ghjunghje à u serviziu di statu avà (ripruvemu)","status.updated":"aghjurnatu {ago}","status.justNow":"à l'istante","status.min":"{n} min fà","status.hours":"{n} o fà","status.days":"{n} g fà","privacy.title":"AI-gile: ciò chì guardemu","privacy.h1":"Ciò chì guardemu","privacy.lede":"In breve: solu ciò chì tù ci mandi, è micca per longu.","privacy.only":"Solu ciò chì tù ci mandi: ciò chì tù scrivi in un furmulariu, cum'è u to email. Nunda altru nant'à tè.","privacy.sealed":"Hè sigillatu cusì chì u nostru servitore ùn u pò leghje: in u to navigatore prima ch'ellu parti (nantu à un navigatore più vechju, appena ch'ellu ghjunghje). Solu a nostra propria tavula u pò apre.","privacy.server":"Hè scancellatu da u servitore appena ch'ellu ghjunghje à a nostra tavula. Tuttu ciò chì ci hè sempre dopu à 30 ghjorni hè scancellatu quantunque.","privacy.board":"U guardemu nantu à a nostra tavula solu finu à ch'è no t'avemu rispostu, po u scancellemu quallà dinù.","privacy.none":"Nisun tracciatore, nisun cookie, nisuna analitica.","privacy.local":"A to lingua è a to scelta chjara o scura fermanu in u to propiu navigatore. Ùn ci sò mai mandate.","privacy.ask":"U voli sparitu più prestu? Rispondi à u nostru email è dicci la.","live.h2":"Guardate cumu hè custruitu, in diretta","live.caption":"Ogni carta hè piatta: videte a forma di u travagliu, micca e parolle.","live.watching.one":"in diretta: {n} chì guardanu","live.watching.other":"in diretta: {n} chì guardanu","live.last.now":"L'ultima carta hè stata spostata ghjustu avà","live.last.min.one":"L'ultima carta hè stata spostata {n} min fà","live.last.min.other":"L'ultima carta hè stata spostata {n} min fà","live.last.hour.one":"L'ultima carta hè stata spostata {n} ora fà","live.last.hour.other":"L'ultima carta hè stata spostata {n} ore fà","live.last.day.one":"L'ultima carta hè stata spostata {n} ghjornu fà","live.last.day.other":"L'ultima carta hè stata spostata {n} ghjorni fà","live.offline":"U tavulone in diretta piglia un pocu di risu. Turnate prestu.","live.cols":"Backlog|À fà|In corsu|Verificazione di a squadra|Per tè da testà|Per a squadra|Fattu"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Delegatu."]},{"n":2,"texts":["Kanban robotica.","Agenti, urganizati.","Idee, custruite."]},{"n":3,"texts":["Kanban per robot.","Idee diventanu funzioni.","Kanban d'agenti gratuitu."]},{"n":5,"texts":["Tavula kanban guidata da agenti.","Tù scrivi carte. Agenti custruiscenu.","Gratuita, lucale, pruvata, un pocu scema."]},{"n":8,"texts":["Una tavula kanban gratuita induve travaglianu agenti AI.","Scrivi una idea. L'agenti a custruiscenu. Tù accetti.","Agile per una persona è tanti robot pazienti."]},{"n":13,"texts":["Una tavula kanban nantu à u to urdinatore induve l'agenti AI piglianu e carte.","Scrivi una idea. Una squadra d'agenti a custruisce. Un tester a verifica.","Gratuita, senza conti, senza tracciatori: una tavula, qualchì robot è tù à cumandà."]},{"n":21,"texts":["AI-gile hè una tavula kanban per travaglià cù agenti AI chì prugrammanu. Elli piglianu e carte; tù e pruvi è l'accetti.","Ogni prugettu hà un capu è una squadra d'agenti AI. Lascia un cumentu nantu à qualsiasi carta è a squadra si mette subitu à travaglià.","Una tavula persunale è gratuita, chì gira nantu à u to urdinatore. I travagliadori sò robot. Quellu chì dice iè sì tù."]},{"n":34,"texts":["Metti l'idee nantu à una tavula. Una squadra d'agenti AI e trasforma in funzioni chì marchjanu, e pruva è te e rende cù i passi per pruvalle. Nunda conta cum'è fattu finu à chì u dici tù.","AI-gile hè una tavula kanban fatta in casa chì Rich hà custruitu cù assai aiutu di l'agenti ch'ella gestisce oghje. Hè gratuita, gira nantu à u to urdinatore è hè spartuta cù l'amichi, micca venduta.","Imagina una tavula kanban nurmale, cù culonne da u Backlog à Fattu, ma induve e carte sò pigliate da agenti AI. Rapportanu l'avanzata, dumandanu quandu sò bluccati, è aspettanu sempre u to pollice in sù."]},{"n":55,"texts":["AI-gile hè una tavula kanban induve a squadra hè fatta d'agenti AI. Ogni prugettu hà un capu chì pianifica u travagliu è aiutanti chì u custruiscenu. Quandu una funzione hè pronta, un tester AI a pruva è face una cattura di schermu, poi ghjunghje in u to mucchjettu. Accettala, o lascia un cumentu è a rifaranu.","Hè natu cum'è u modu d'una persona di seguità parechje sessioni di prugrammazione AI à una volta, è hè criscutu finu à diventà una vera tavula. Gira nantu à a to macchina, ùn vole nisun contu, è ùn hà nisun tracciatore. Hè gratuita per l'amichi è i curiosi. Hè dinù incompiuta, dunque aspetta bordi grezzi è qualchì surpresa.","Eccu a versione onesta. Tù devi sempre avè l'idee, è devi sempre verificà i risultati. Ciò chì face AI-gile hè tuttu ciò chì ci hè trà i dui: tene e carte in ordine, sveglia l'agente ghjustu quandu lasci un cumentu, mostra esattamente ciò chì hè cambiatu, è mette tuttu in un mucchjettu cortu per tè."]},{"n":89,"texts":["AI-gile hè una tavula kanban gratuita chì fai girà nantu à u to propiu urdinatore. Invece di persone, ogni prugettu hà una squadra d'agenti AI: un capu chì trasforma e to idee in carte è in un pianu, è aiutanti chì piglianu e carte per ordine di prioriteta. Quandu qualcosa hè custruitu, un tester AI seguita i passi di prova è ti mostra ciò chì hà vistu. Poi aspetta in un mucchjettu chjamatu Per tè. L'accetti, o lasci un cumentu è a squadra pruva torna. Nunda ghjunghje mai à Fattu senza di tè.","Qualchì cosa chì forse ùn t'aspetti micca. Una guardia di notte tene piena a culonna À fà mentre dorme, sceglendu carte chì ùn anu bisognu d'una risposta da tè. Un cuntatore di token mostra quantu l'agenti anu adupratu oghje è sta settimana, è u No Token Mode li dice di piantà di spende. Pudi scrive à l'amichi, è i missaghji privati sò cifrati da un capu à l'altru. A tavula parla circa 120 lingue, cumprese l'olandese, u fiammingu, u pirata è u klingon. Nunda di tuttu què costa un centesimu, è nimu ùn prova à vendeti nunda.","AI-gile hè un picculu prugettu persunale, micca una sucietà. Rich vulia curà parechji prugetti di prugrammazione AI senza apre ogni app per verificalli, allora ellu è l'agenti anu custruitu una tavula per què, è dopu anu adupratu a tavula per custruisce u restu d'elli stessi. Hè in pre-alfa chjosa, chì vole dì ch'ella funziona, più o menu, per una manata d'amichi. Ùn ci hè pagina di prezzi, nè newsletter, nè pianu di crescita. S'ellu ti pare utile, pudi dumandà di pruvallu quandu s'aprerà un pocu di più."]},{"n":144,"texts":["AI-gile hè una tavula kanban per una persona è tanti agenti AI. Gira nantu à u to propiu urdinatore è hè compiamente gratuita. Aghjunghji prugetti, è ogni prugettu hà un capu è una squadra chjuca. Chjachjeri cù u capu, un pocu cum'è nantu à Discord, è discrivi una idea; u capu a trasforma in carte è in un pianu, poi aspetta ch'è tù prema Go. A squadra travaglia e carte per ordine di prioriteta, cù una linea di cumandi simplice fatta per i mudelli di lingua. Nanzu chì qualcosa ti torni, un tester AI seguita i passi in una copia di l'app è attacca una cattura di schermu. U travagliu compiu ghjunghje in u to mucchjettu cù i fugliali cambiati è a differenza. L'accetti, o lasci un cumentu è a squadra si sveglia è pruva torna. Solu tù pò spustà una carta in Fattu. Nisun contu, nisun tracciatore, nisun cookie, è tuttu stà nantu à u to urdinatore.","Una ghjurnata cù AI-gile, à pocu pressu. A sera lasci qualchì cumentu: stu buttone hè in u locu sbagliatu, quella lista duverebbe esse urdinata, puderiamu avè un modu scuru. Vai à durmite. L'agenti leghjenu i cumenti, facenu i cambiamenti, i pruvanu è i rendenu. Se À fà s'asciuga, a guardia di notte u riempie da u backlog cù carte chì ùn anu bisognu d'alcuna risposta da tè. À a mattina ci hè un mucchjettu cortu: una coppia di dumande è qualchì cosa à pruvà, ognuna cù passi chì pò seguità una persona insunnuliata è una cattura di schermu chì mostra ch'ella funziona. Clicchi, accetti e bone è rimandi u restu. Un cuntatore di token mostra ciò chì hà adupratu tuttu què, è u No Token Mode hè per e settimane magre. Poi fai colazione, chì l'agenti ùn ponu ancu aiutà à fà.","Prima, ciò chì AI-gile ùn hè micca. Ùn hè una startup, ùn hè in vendita, è nimu ùn raccoglie i to dati. Hè una tavula gratuita chì gira nantu à u to urdinatore, senza conti, senza tracciatori è senza cookie. Ciò ch'ella hè: un locu ordinatu per vede tutti i prugetti di prugrammazione AI à una volta, cù una squadra d'agenti chì face e carte è tù chì pigli e decisioni. Unisce e carte parenti, currege i tituli imbrugliati, è tene d'ochju quantu u codice firmeghja leggeru. Parla circa 120 lingue, da l'olandese è u fiammingu finu à u pirata è u klingon. L'amichi ponu scrivesi, in privatu è cifratu. Hè statu custruitu da Rich è un gran numeru d'agenti pazienti, soprattuttu aduprandusi. Hè in pre-alfa chjosa, dunque hè grezzu in certi lochi. S'ellu ti pare un spassu, dumanda cù gentilezza è forse entrerai prestu."]}],"quips":{"1":"Una parolla. Audace. Forse troppu audace.","3":"Trè parolle. Dighjà più onesta di a maiò parte di e pagine di prudotti.","8":"Ottu parolle. Sempre più corta d'una stand-up.","21":"E lunghezze sò story points, per via. Sicuru ch'elle sò.","55":"Cinquantacinque parolle. Dui carte sò state compie mentre leghji.","144":"Hè quella longa. Ùn ci hè 233. L'agenti sò andati à durmite."}},"timeline":{"first-idea.name":"A prima idea","first-idea.line":"A primissima cunversazione, nanzu ch'ellu esistessi qualsiasi codice.","first-board.name":"Prima tavula","first-board.line":"Una tavula chì seguita a so propria custruzzione: carte, culonne, tirà è lascià, prugetti.","team-roles.name":"Squadra è roli","team-roles.line":"Prufili d'agenti, mudelli di squadra, spazii è quale face ciò chì.","install.name":"Installazione è versioni","install.line":"Un zip chì un amicu pò installà, aghjurnamenti autumatichi, canali è ritornu in daretu.","usage-saver.name":"Risparmiu d'usu","usage-saver.line":"Misurà ciò chì costanu l'esecuzioni, tene u codice leggeru, risparmià u to limite.","friends.name":"Amichi è spartera","friends.line":"Missaghji privati, un relé cifratu, invitazioni, roli è prugetti spartuti.","languages.name":"Lingue","languages.line":"Ogni testu di schermu in un fugliale di lingua, cù l'olandese è u fiammingu prima.","ai-tester.name":"Tester AI","ai-tester.line":"Un tester verifica prima ogni cunsegna è mostra ciò chì hà vistu.","website.name":"U situ web","website.line":"aigile.lol, l'anteprima è sta cronologia.","streaming.name":"Chat è streaming","streaming.line":"Discord, Twitch, OBS, modu streamer, GIF è emoji.","no-ai.name":"Edizione senza AI","no-ai.line":"Una tavula per quelli chì prugrammanu senza AI, è tavule pubbliche.","night-watch.name":"Guardia di notte","night-watch.line":"Un guardianu è un Scrum Master tenenu e squadre à u travagliu mentre dorme.","p-more.name":"Tuttu u restu","p-more.line":"Idee più chjuche chì aspettanu sempre u so turnu.","p-android.name":"Telefonu è Android","p-android.line":"Ghjunghje à a to tavula da un telefonu, poi una app Android nativa.","p-release.name":"Alfa è oltre","p-release.line":"Alfa chjosa, u situ in diretta, poi a beta.","p-languages.name":"Più lingue","p-languages.line":"130 lingue, è un modu d'immersione per quelli chì amparanu.","p-engines.name":"Più mutori AI","p-engines.line":"Sceglie Claude, Codex, Gemini, Copilot o Cursor per ogni agente.","p-pro.name":"Pratica prufessiunale","p-pro.line":"Etichette di risicu, porte di fusione, carte d'incidenti è paracarri.","p-self.name":"Curà di tè","p-self.line":"Modu stancu, rammentatori di cura di sè è 4:20.","p-servers.name":"Servitori è crescita","p-servers.line":"Paramettri glubali di i servitori, roli è pianificazione per crescere.","p-livestream.name":"Extra di streaming","p-livestream.line":"Chat di Twitch, emoji persunalizati è una vista pubblica in diretta."},"words":{"button":"📖 Termini di u mistieru","h":"📖 Parolle spiegate","intro":"E parolle chì tù scontri in AI-gile, in lingua simplice: custruiscelu, cambiallu senza periculu, mantenelu in funziunamentu per a ghjente chì l'adopra, è travaglià in squadra cù l'IA.","search":"Circà una parolla…","none":"Nisuna parolla currisponde.","close":"Chjode","count":{"one":"{count} parolla","other":"{count} parolle"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Custruisce"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Cambià senza periculu"},{"id":"run","name":"🛎️ Gestisce un serviziu"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have."},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Idee è travagliu micca ancu pianificati. Nunda quì hè travagliatu finu à chì passa in À fà."},{"id":"sprint","g":"agile","word":"Sprint","text":"Un cortu periodu di travagliu (spessu una o duie settimane) cù un inseme di carte cunvenutu da compie.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Un puntu prestu : ciò chì ogni membru hà fattu, ciò chì face dopu, è ciò chì u ferma.","also":["standup","stand-ups"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Una tavula cù colonne (À fà, In corsu, Fattu) induve e carte vanu da manca à diritta mentre u travagliu avanza."},{"id":"wip","g":"agile","word":"Limite WIP","text":"Work in progress : u massimu di carte chì una colonna deve tene, perchè a squadra compii e cose nanzu di principià ne di più.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definizione di Fattu","text":"A lista corta di a squadra di ciò chì vole dì “compiu”, cum'è pruvatu è spiegatu, nanzu chì una carta ti sia data. A so gemella, a Definizione di Prontu, dice quandu una carta hè abbastanza chjara per principià.","also":["Definizione di Prontu","Definition of Done","Definition of Ready"]},{"id":"retro","g":"agile","word":"Retro","text":"Un sguardu in daretu à cumu travaglia a squadra, per mette si d'accordu nant'à una cosa da fà megliu. In AI-gile una retro prupone un cambiamentu in u modu di travaglià di a squadra, è tù dici Vai o Ancu no.","also":["retros","retrospettiva","retrospective"]},{"id":"swarm","g":"agile","word":"Sciame","text":"Tutti à u ponte: ogni squadra lascia l'altru travagliu per aiutà nant'à un prughjettu urgente finchè ùn hè risoltu. L'altri prughjetti aspettanu intantu.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Quellu chì face scorre u travagliu: vede e carte bluccate, spinghje e squadre è ti ramenta ciò chì aspetta. In AI-gile u Lead Scrum Master face què per tutti i prughjetti.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"U cartulare di u prughjettu cù u codice è tutta a storia di i commit, spessu tenutu ancu nantu à GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Una linea di travagliu à parte in u codice, per pudè fà cambiamenti senza tuccà a versione principale.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Una istantanea salvata di u codice, cù una nota corta di ciò chì hè cambiatu. Pudi sempre turnà à una.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Mandà l'istantanee salvate (commits) da stu urdinatore à GitHub, perchè sianu salvate è sparte."},{"id":"merge","g":"build","word":"Merge","text":"Riunisce i cambiamenti d'una branch in a versione principale."},{"id":"pr","g":"build","word":"Pull request","text":"Dumandà chì i cambiamenti d'una branch sianu verificati è fusi in a versione principale.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Mette in ordine u codice senza cambià ciò chì face : schedarii più chjuchi, nomi più chjari, menu ripetizioni."},{"id":"bug","g":"build","word":"Bug","text":"Qualcosa chì ùn funziona micca cum'ellu duverebbe.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Revisione tra pari","text":"Un secondu paghju d'ochji: un'altra IA verifica u travagliu di ogni carta nanzu ch'ellu ti ghjunghji, cusì menu sbagli passanu.","also":["revisione di u codice","peer review","code review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor."},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiler"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"Pruvà un travagliu finitu per verificà chì face ciò chì era statu dumandatu, nanzu di accettallu.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Accurtatura di quality assurance (garanzia di qualità): i cuntrolli autumatichi chì giranu nanzu chì qualcosa passi in pruduzzione. Quandu QA hè rossu, qualcosa hà fallitu, è ùn pò passà in pruduzzione finchè ùn hè currettu.","also":["cuntrolli di qualità","garanzia di qualità","quality checks"]},{"id":"testpile","g":"test","word":"Pila di prove","text":"E carte compie chì aspettanu chì tù e provi, una dopu l'altra. Accetta ne una o rimandala cù una nota, è vene a seguente.","also":["pile di prove","test pile"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Mette una versione nova in linea, per esempiu nantu à un servitore induve a ghjente a usa."},{"id":"release","g":"change","word":"Versione","text":"Un pacchettu cù un nome di travagliu compiu chì passa in pruduzzione inseme, cù note brevi nant'à ciò chì hà cambiatu. 🚀 Versioni scrive e note à partesi da e carte fatte.","also":["versioni","release"]},{"id":"rollback","g":"change","word":"Rollback","text":"Turnà à l'ultima versione chì funziunava quandu una nova face guai. In AI-gile face una lista di cuntrollu cù i passi per disfà scritti nant'à ogni cambiamentu.","also":["ritornu in daretu","rivolta","roll back"]},{"id":"live","g":"change","word":"Pruduzzione","text":"A versione vera chì a ghjente adopra, à u cuntrariu d'una copia per pruvà e cose. I sviluppatori a chjamanu ancu production o “live”.","also":["in diretta","production","live"],"noTip":1},{"id":"change","g":"change","word":"Cambiamentu","text":"Un cambiamentu prughjettatu nant'à qualcosa chì a ghjente ci conta, scrittu prima: chì, perchè, u risicu, quandu, è cumu disfallu. Principiane unu cù 🔀 Dumandà un cambiamentu.","also":["cambiamenti","dumanda di cambiamentu","change request"],"noTip":1},{"id":"risk","g":"change","word":"Risicu","text":"Qualcosa chì puderia andà male, cù un puntu secondu quantu hè prubabile è quantu seria gravu. ⚠️ Risichi i tene in una lista, u puntu più altu prima, ognunu cù una data per fighjallu torna.","also":["risichi","registru di i risichi","risk"]},{"id":"chgwin","g":"change","word":"Finestra di cambiamentu","text":"L'ore quandu i cambiamenti ponu passà in pruduzzione, cum'è un marti di sera tranquillu. Fora d'una finestra una carta di cambiamentu ùn pò esse compia, eccettu s'ella hè un'urgenza.","also":["finestre di cambiamentu","change window"]},{"id":"gonogo","g":"change","word":"Si va / Ùn si va","text":"Un votu rapidu ghjustu nanzu chì un cambiamentu passi in pruduzzione: ogni persona chì deve appruvà dice Si va o Ùn si va. Ùn và avanti chè quand'elli sò d'accordu.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Appruvazione","text":"Aspettà un sì nanzu chì u travagliu principii. Una carta prupusta da un amicu, o un cambiamentu, aspetta in ✅ Appruvazioni finchè tù ùn l'appruvi o ùn la ricusi.","also":["appruvazioni","approval"]},{"id":"quiettime","g":"change","word":"Tempu tranquillu","text":"Un periodu, cum'è una diretta, una demo o a notte, quandu nunda passa in pruduzzione. E squadre cuntinueghjanu à travaglià è à pruvà, ma u passu in pruduzzione aspetta ch'ellu finisca. Altrò si chjama ghjelu di i cambiamenti.","also":["tempi tranquilli","ghjelu di i cambiamenti","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company."},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Serviziu","text":"Qualcosa chì tù hai custruitu è chì a ghjente ci conta, cum'è un situ web o un'appiecazione, curatu perchè cuntinueghji à funziunà. Marca “Stu prughjettu hè un serviziu” è dì ciò ch'ellu offre, quale l'adopra è quale hè di guardia.","also":["servizii","service"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Cuntrollu di funziunamentu","text":"Un cuntrollu autumaticu, ogni pochi minuti, chì u to serviziu risponde sempre. S'ellu falla parechje volte di fila, AI-gile apre da per ellu una carta d'incidente.","also":["tempu di funziunamentu","uptime","uptime check"]},{"id":"statuspage","g":"run","word":"Pagina di statu","text":"Una pagina publica chì mostra s'è un serviziu funziona (verde, aranciu o rossu) cù l'ultima nutizia, cusì a ghjente chì l'adopra pò verificà invece di dumandà.","also":["pagine di statu","status page"]},{"id":"desk","g":"run","word":"Serviziu d'assistenza","text":"Induve arrivanu e dumande è e segnalazioni di a ghjente chì adopra u to serviziu. AI-gile classa ognuna cum'è richiesta, incidente o idea, è ti a dice quandu pare qualcosa digià segnalatu.","also":["servizii d'assistenza","assistenza","helpdesk"]},{"id":"svcrequest","g":"run","word":"Richiesta di serviziu","text":"Qualchissia chì dumanda qualcosa di currente, cum'è un contu novu o un pocu d'aiutu, piuttostu chè di segnalà chì qualcosa hè rottu. Aspetta u so turnu; un incidente passa prima.","also":["richieste di serviziu"]},{"id":"incident","g":"run","word":"Incidente","text":"Qualcosa chì hè rottu avà per a ghjente chì l'adopra, cum'è u situ web in panna. Una carta 🔥 incidente passa davanti à a fila: fallu funziunà torna vene prima.","also":["incidenti","incident"]},{"id":"major","g":"run","word":"Incidente maiore","text":"Un incidente grossu: assai ghjente tocca, o soldi o dati in periculu. Un buttone mette tutte e squadre nantu (sciame), sveglia quellu chì hè di guardia è dumanda un aghjurnamentu di statu ogni 30 minuti.","also":["incidenti maiori","major incident"]},{"id":"oncall","g":"run","word":"Di guardia","text":"Esse quellu chì risponde quandu qualcosa si rompe, ancu di notte. Ogni serviziu hà un membru di a squadra di guardia, svegliatu u primu per i so incidenti.","also":["guardia","on call","on-call"]},{"id":"replyby","g":"run","word":"Ora di risposta","text":"Quantu tempu una carta pò aspettà una prima risposta, per esempiu un'ora per un incidente. Dopu piglia un orologliu rossu, cusì nunda ùn hè scurdatu in silenziu. Si chjama ancu scopu di risposta.","also":["ore di risposta","scopu di risposta","response target"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Un sguardu cortu in daretu dopu un incidente: ciò chì hè accadutu, ciò chì hà aiutatu è ciò chì ci vole à cambià, senza incolpà à nimu. Un incidente ùn pò esse chjosu senza unu.","also":["postmortem","revisione dopu l'incidente"]},{"id":"problem","g":"run","word":"Prublema","text":"A causa piatta daretu à unu o parechji incidenti. Una carta 🧩 prublema raggruppa l'incidenti chì tornanu sempre, cusì a causa hè trovata è currigiuta per sempre.","also":["prublemi","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Causa radica","text":"A vera ragione per chì qualcosa s'hè rottu, è micca solu ciò chì tù hai vistu andà male. Curreghji a causa radica è l'incidente ùn torna più.","also":["cause radiche","root cause"]},{"id":"workaround","g":"run","word":"Suluzione pruvisoria","text":"Un modu di mantene e cose in funziunamentu finchè a vera currezzione sia pronta, cum'è rilancià qualcosa quandu si blocca. Hè scritta nant'à a carta di u prublema cusì nimu ùn hà da truvalla torna.","also":["suluzioni pruvisorie","workaround"]},{"id":"knownerror","g":"run","word":"Errore cunnisciutu","text":"Un prublema chì a so causa hè capita è chì hà una suluzione pruvisoria, ma ùn hè ancu currettu. 🧩 Errori cunnisciuti i lista, cusì ognunu adopra a suluzione pruvisoria invece di circà torna.","also":["errori cunnisciuti","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Istruzzioni passu à passu per currege un tipu di guai cunnisciutu, cusì hè fattu di listessa manera, prestu, ogni volta. Dopu un incidente maiore a squadra ne pò prupone unu per chì tù l'appruvi.","also":["runbooks","manuale d'operazione"]},{"id":"ci","g":"run","word":"Elementu di cunfigurazione","text":"Una cosa da quale u to serviziu dipende, cum'è un servitore, un duminiu, un certificatu, una chjave o un furnitore. 🗂️ Elementi di cunfigurazione i elenca per serviziu, cusì vedi ciò chì un incidente tocca è ciò chì ci vole à rinnovà o à salvà.","also":["elementi di cunfigurazione"]},{"id":"expiry","g":"run","word":"Data di scadenza","text":"AI-gile sorveglia date cum'è quandu un certificatu o un duminiu scade. In i 30 ghjorni nanzu à a data face una carta per rinnovallu, cusì nunda ùn si ferma di colpu.","also":["date di scadenza","scadenza","sorveglianza di e scadenze"]},{"id":"backup","g":"run","word":"Copia di salvezza","text":"Una copia salvata di i to dati di prima, per ricorre ci s'è qualcosa hè persu o guastu. AI-gile face ogni ghjornu una copia di salvezza di i to tavulini.","also":["copie di salvezza","backup"]},{"id":"restore","g":"run","word":"Risturà","text":"Rimette i dati da una copia di salvezza. Una copia di salvezza conta daveru solu quandu sai ch'ella pò esse risturata, allora vale a pena di pruvà da tantu in tantu.","also":["risturazione","risturatu","restore"]},{"id":"svcreview","g":"run","word":"Revisione di serviziu","text":"Un sguardu in daretu nant'à un mese di un serviziu: incidenti aperti è riparati, quantu prestu a ghjente hà avutu una risposta, funziunamentu è token aduprati. A Revisione mensile a mostra per ogni serviziu.","also":["revisioni di serviziu","revisione mensile","revisioni mensili"]},{"id":"accessreview","g":"run","word":"Revisione d'accessu","text":"Verificà ogni 90 ghjorni quale pò sempre entre: ligami di cundivisione, roli di l'amichi è sicreti tenuti. Teni o cacci ognunu, cusì l'accessi vechji ùn restanu micca.","also":["revisioni d'accessu"]},{"id":"improvements","g":"run","word":"Lista di i miglioramenti","text":"Tuttu ciò chì a squadra hà decisu di fà megliu, in un locu solu: suggerimenti di a retro, azzioni di e revisioni è currezzioni di i prublemi, ognunu cù u so statu. A trovi sottu 📈 Miglioramenti.","also":["liste di i miglioramenti","miglioramenti"]},{"id":"tokencap","g":"run","word":"Tettu di token","text":"Un limitu mensile di i token chì l'agenti di un serviziu ponu aduprà. À 80% ricevi un avertimentu; à 100% u so travagliu in fondu aspetta u mese dopu o finchè tù ùn alzi u tettu.","also":["tetti di token"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day."},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice."},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing."},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service."},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agente","text":"Una IA chì travaglia da sola nantu à un compitu : leghje u codice, face cambiamenti, eseguisce verificazioni, è ti torna rapportu.","also":["agenti"]},{"id":"token","g":"ai","word":"Token","text":"L'unità in a quale l'usu di l'IA hè cuntatu : à pocu pressu uni pochi di lettere di testu lette o scritte. Menu token, più pianu chì ferma.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Una cumanda chjuca chì gira da sè à un mumentu datu, p.e. quandu una sessione IA principia, perchè a squadra senti i to cummenti.","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
